function onMessage(ctx, event) {
  const profile = profilesCache.get(event.deviceId);
  const threshold = profile ? profile.threshold : globalDefault;
  if (event.value > threshold && (Date.now() - (profile?.lastAlertTs ?? 0)) > TTL) {
    emit({id: `${event.deviceId}-${event.ts}`, deviceId: event.deviceId, value: event.value, ts: event.ts});
  }
